export type StatusClass = "success" | "client" | "server";

export interface LogEntry {
  id: string;
  time: number;
  method: "GET" | "POST" | "PATCH" | "DELETE";
  path: string;
  status: number;
  duration: number;
  region: string;
  ip: string;
  key: string;
  userAgent: string;
}

export const statusClasses: { id: StatusClass; name: string; color: string }[] =
  [
    { id: "success", name: "2xx", color: "var(--ts-chart-1)" },
    { id: "client", name: "4xx", color: "var(--ts-chart-3)" },
    { id: "server", name: "5xx", color: "var(--ts-chart-5)" },
  ];

export function statusClass(status: number): StatusClass {
  if (status >= 500) return "server";
  if (status >= 400) return "client";
  return "success";
}

function random(seed: number) {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

const routes: { method: LogEntry["method"]; path: string; weight: number }[] = [
  { method: "POST", path: "/v1/messages", weight: 30 },
  { method: "GET", path: "/v1/messages/{id}", weight: 22 },
  { method: "GET", path: "/v1/contacts", weight: 14 },
  { method: "PATCH", path: "/v1/contacts/{id}", weight: 8 },
  { method: "POST", path: "/v1/batches", weight: 6 },
  { method: "GET", path: "/v1/webhooks", weight: 6 },
  { method: "DELETE", path: "/v1/webhooks/{id}", weight: 3 },
  { method: "POST", path: "/v1/auth/token", weight: 11 },
];

const regions = ["iad1", "iad1", "iad1", "fra1", "sfo1"];
const keys = ["rk_live_…4f2a", "rk_live_…91cd", "rk_live_…07be"];
const agents = [
  "relay-node/4.2.0 node/22.11.0",
  "relay-python/3.8.1 python/3.13",
  "curl/8.9.1",
];

export const windowEnd = Date.UTC(2026, 9, 28, 14, 32, 10);
export const windowMinutes = 30;

function pick<T>(next: () => number, items: T[]) {
  return items[Math.floor(next() * items.length)];
}

function routeFor(next: () => number) {
  const total = routes.reduce((sum, route) => sum + route.weight, 0);
  let roll = next() * total;
  for (const route of routes) {
    roll -= route.weight;
    if (roll <= 0) return route;
  }
  return routes[0];
}

function statusFor(
  next: () => number,
  method: LogEntry["method"],
  minute: number,
) {
  const incident = minute >= 11 && minute <= 14;
  const roll = next();
  if (incident && roll < 0.32) return pick(next, [500, 502, 503]);
  if (roll < 0.012) return 500;
  if (roll < 0.05) return pick(next, [400, 401, 404, 422, 429]);
  return method === "POST" ? 201 : method === "DELETE" ? 204 : 200;
}

export function createEntry(next: () => number, time: number, index: number) {
  const route = routeFor(next);
  const minute = Math.floor((windowEnd - time) / 60_000);
  const status = statusFor(next, route.method, minute);
  const base = route.path === "/v1/batches" ? 420 : 60;
  const slow = status >= 500 ? 1800 : 0;
  const id = Math.floor(next() * 36 ** 8)
    .toString(36)
    .padStart(8, "0");
  return {
    id: `req_${id}${index.toString(36)}`,
    time,
    method: route.method,
    path: route.path.replace(
      "{id}",
      `${route.path.includes("contacts") ? "ct" : route.path.includes("webhooks") ? "wh" : "msg"}_${Math.floor(next() * 36 ** 6).toString(36)}`,
    ),
    status,
    duration: Math.round(base + next() * 180 + slow * next()),
    region: pick(next, regions),
    ip: `${pick(next, [34, 52, 18, 104])}.${Math.floor(next() * 255)}.${Math.floor(next() * 255)}.${Math.floor(next() * 255)}`,
    key: pick(next, keys),
    userAgent: pick(next, agents),
  } satisfies LogEntry;
}

function buildLogs() {
  const next = random(2814);
  const entries: LogEntry[] = [];
  let time = windowEnd;
  let index = 0;
  while (time > windowEnd - windowMinutes * 60_000) {
    entries.push(createEntry(next, time, index));
    index += 1;
    time -= Math.round(4_000 + next() * 14_000);
  }
  return entries;
}

export const initialLogs = buildLogs();

export function seededRandom(seed: number) {
  return random(seed);
}

const clock = new Intl.DateTimeFormat("en-US", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
  timeZone: "UTC",
});

const full = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
  timeZone: "UTC",
});

export function formatClock(time: number) {
  return clock.format(new Date(time));
}

export function formatFull(time: number) {
  return `${full.format(new Date(time))} UTC`;
}

export function responseBody(entry: LogEntry) {
  if (entry.status === 204) return "";
  if (entry.status >= 500) {
    return JSON.stringify(
      {
        error: {
          type: "upstream_unavailable",
          message: "The delivery provider did not answer in 10 seconds.",
          request_id: entry.id,
        },
      },
      null,
      2,
    );
  }
  if (entry.status >= 400) {
    const errors: Record<number, [string, string]> = {
      400: [
        "invalid_request",
        "The field 'to' must be a phone number or email.",
      ],
      401: ["unauthorized", "The API key is not valid or was revoked."],
      404: ["not_found", "No resource has this ID."],
      422: ["validation_failed", "The template has 2 missing variables."],
      429: ["rate_limited", "Slow down. The limit is 100 requests per second."],
    };
    const [type, message] = errors[entry.status] ?? [
      "error",
      "Request failed.",
    ];
    return JSON.stringify(
      { error: { type, message, request_id: entry.id } },
      null,
      2,
    );
  }
  const last = entry.path.split("/").at(-1) ?? "";
  const resource = entry.path.split("/")[2] ?? "";
  const objects: Record<string, string> = {
    messages: "message",
    contacts: "contact",
    webhooks: "webhook",
    batches: "batch",
    auth: "token",
  };
  const object = objects[resource] ?? resource;
  return JSON.stringify(
    {
      id: last.includes("_")
        ? last
        : `${object.slice(0, 3)}_${entry.id.slice(4, 12)}`,
      object,
      status: entry.method === "POST" ? "queued" : "active",
    },
    null,
    2,
  );
}

"use client";

import { MagnifyingGlassIcon, PulseIcon } from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { Badge } from "../../vip-ui/badge";
import { Button } from "../../vip-ui/button";
import {
  CodeBlock,
  CodeBlockActions,
  CodeBlockBody,
  CodeBlockHeader,
  CodeBlockTitle,
} from "../../vip-ui/code-block";
import { CopyButton } from "../../vip-ui/copy-button";
import {
  DescriptionDetail,
  DescriptionList,
  DescriptionTerm,
} from "../../vip-ui/description-list";
import { GridList, GridListItem } from "../../vip-ui/grid-list";
import { useMediaQuery } from "../../vip-ui/hooks";
import {
  ResizableGroup,
  ResizableHandle,
  ResizablePanel,
} from "../../vip-ui/resizable";
import { ScrollArea } from "../../vip-ui/scroll-area";
import { SearchField } from "../../vip-ui/search-field";
import {
  Sheet,
  SheetBody,
  SheetClose,
  SheetHeader,
  SheetTitle,
} from "../../vip-ui/sheet";
import { Switch } from "../../vip-ui/switch";
import { ToggleButton } from "../../vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../vip-ui/toggle-button-group";
import { cn } from "../../vip-ui/utils";
import {
  createEntry,
  formatClock,
  formatFull,
  initialLogs,
  type LogEntry,
  responseBody,
  type StatusClass,
  seededRandom,
  statusClass,
  statusClasses,
  windowMinutes,
} from "./data";
import { LogHistogram } from "./log-histogram";

type Filter = "all" | StatusClass;

const badgeVariant = {
  success: "success",
  client: "warning",
  server: "error",
} as const satisfies Record<StatusClass, string>;

function StatusBadge({ status }: { status: number }) {
  return (
    <Badge variant={badgeVariant[statusClass(status)]} className="tabular-nums">
      {status}
    </Badge>
  );
}

function LogDetails({ entry }: { entry: LogEntry }) {
  const body = responseBody(entry);
  return (
    <div className="grid content-start gap-5">
      <div className="grid gap-2">
        <div className="flex items-center gap-2">
          <StatusBadge status={entry.status} />
          <span className="font-mono text-xs text-muted-foreground">
            {entry.duration} ms
          </span>
        </div>
        <p className="font-mono text-sm font-medium break-all">
          {entry.method} {entry.path}
        </p>
      </div>
      <DescriptionList className="text-sm">
        <DescriptionTerm>Request ID</DescriptionTerm>
        <DescriptionDetail>
          <span className="flex min-w-0 items-center gap-1">
            <span className="truncate font-mono text-xs">{entry.id}</span>
            <CopyButton
              value={entry.id}
              variant="ghost"
              size="xs"
              iconOnly
              aria-label="Copy request ID"
            />
          </span>
        </DescriptionDetail>
        <DescriptionTerm>Time</DescriptionTerm>
        <DescriptionDetail>{formatFull(entry.time)}</DescriptionDetail>
        <DescriptionTerm>Region</DescriptionTerm>
        <DescriptionDetail className="font-mono text-xs">
          {entry.region}
        </DescriptionDetail>
        <DescriptionTerm>API key</DescriptionTerm>
        <DescriptionDetail className="font-mono text-xs">
          {entry.key}
        </DescriptionDetail>
        <DescriptionTerm>Client IP</DescriptionTerm>
        <DescriptionDetail className="font-mono text-xs">
          {entry.ip}
        </DescriptionDetail>
        <DescriptionTerm>User agent</DescriptionTerm>
        <DescriptionDetail className="font-mono text-xs break-all">
          {entry.userAgent}
        </DescriptionDetail>
      </DescriptionList>
      {body ? (
        <CodeBlock code={body} language="json">
          <CodeBlockHeader>
            <CodeBlockTitle>Response body</CodeBlockTitle>
            <CodeBlockActions />
          </CodeBlockHeader>
          <CodeBlockBody />
        </CodeBlock>
      ) : (
        <p className="text-sm text-muted-foreground">No response body.</p>
      )}
    </div>
  );
}

export function LogExplorer() {
  const [logs, setLogs] = useState(initialLogs);
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [live, setLive] = useState(false);
  const [selectedId, setSelectedId] = useState(
    () =>
      initialLogs.find((entry) => entry.status >= 500)?.id ?? initialLogs[0].id,
  );
  const [sheetOpen, setSheetOpen] = useState(false);
  const isWide = useMediaQuery("(min-width: 1024px)");
  const random = useRef(seededRandom(77));

  useEffect(() => {
    if (!live) return;
    const timer = window.setInterval(() => {
      setLogs((current) => {
        const next = random.current;
        const time = current[0].time + Math.round(800 + next() * 2_400);
        const cutoff = time - windowMinutes * 60_000;
        return [
          createEntry(next, time, current.length),
          ...current.filter((entry) => entry.time > cutoff),
        ];
      });
    }, 1_600);
    return () => window.clearInterval(timer);
  }, [live]);

  const terms = query.trim().toLowerCase();
  const matching = logs.filter((entry) =>
    terms
      ? `${entry.id} ${entry.method} ${entry.path} ${entry.status} ${entry.region}`
          .toLowerCase()
          .includes(terms)
      : true,
  );
  const visible = matching.filter(
    (entry) => filter === "all" || statusClass(entry.status) === filter,
  );
  const counts = {
    all: matching.length,
    success: matching.filter((entry) => statusClass(entry.status) === "success")
      .length,
    client: matching.filter((entry) => statusClass(entry.status) === "client")
      .length,
    server: matching.filter((entry) => statusClass(entry.status) === "server")
      .length,
  };
  const selected = logs.find((entry) => entry.id === selectedId) ?? null;
  const errorRate =
    logs.length === 0
      ? 0
      : (logs.filter((entry) => entry.status >= 500).length / logs.length) *
        100;

  function choose(id: string) {
    setSelectedId(id);
    if (!isWide) setSheetOpen(true);
  }

  const list =
    visible.length === 0 ? (
      <div className="grid h-full place-items-center p-6 text-center">
        <div className="grid justify-items-center gap-2">
          <MagnifyingGlassIcon
            size={22}
            className="text-muted-foreground"
            aria-hidden="true"
          />
          <p className="text-sm font-medium">No requests match</p>
          <Button
            variant="outline"
            size="sm"
            onPress={() => {
              setQuery("");
              setFilter("all");
            }}
          >
            Clear filters
          </Button>
        </div>
      </div>
    ) : (
      <ScrollArea className="h-full" aria-label="Requests">
        <GridList
          aria-label="Requests"
          items={visible}
          selectionMode={isWide ? "single" : "none"}
          selectionBehavior="replace"
          disallowEmptySelection
          selectedKeys={selected ? [selected.id] : []}
          onSelectionChange={(keys) => {
            const [key] = keys === "all" ? [] : [...keys];
            if (key !== undefined) choose(String(key));
          }}
          onAction={(key) => choose(String(key))}
          className="gap-0 rounded-none border-0 bg-transparent p-1 shadow-none"
        >
          {(entry) => (
            <GridListItem
              id={entry.id}
              textValue={`${entry.method} ${entry.path} ${entry.status}`}
              className="grid min-h-9 grid-cols-[4.5rem_2.5rem_minmax(0,1fr)] sm:grid-cols-[4.5rem_3.25rem_3rem_minmax(0,1fr)_4rem] gap-3 rounded-md px-3 py-1.5 font-mono text-xs"
            >
              <span className="text-muted-foreground tabular-nums">
                {formatClock(entry.time)}
              </span>
              <span className="text-muted-foreground max-sm:hidden">
                {entry.method}
              </span>
              <span
                className={cn(
                  "tabular-nums",
                  entry.status >= 500 && "font-semibold text-destructive",
                  entry.status >= 400 &&
                    entry.status < 500 &&
                    "text-warning-foreground",
                )}
              >
                {entry.status}
              </span>
              <span className="truncate">{entry.path}</span>
              <span className="text-end text-muted-foreground tabular-nums max-sm:hidden">
                {entry.duration} ms
              </span>
            </GridListItem>
          )}
        </GridList>
      </ScrollArea>
    );

  return (
    <div className="min-h-svh bg-background">
      <header className="border-b border-border/70 bg-card">
        <div className="mx-auto flex h-14 max-w-360 items-center gap-2.5 px-4 sm:px-6">
          <span className="grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground">
            <PulseIcon size={17} weight="bold" aria-hidden="true" />
          </span>
          <span className="text-sm font-semibold tracking-[-0.02em]">
            Relay
          </span>
          <span aria-hidden="true" className="text-muted-foreground/60">
            /
          </span>
          <span className="text-sm text-muted-foreground">Logs</span>
          <Badge variant="outline" className="ms-auto">
            Production
          </Badge>
        </div>
      </header>

      <main className="mx-auto grid max-w-360 gap-4 px-4 py-6 sm:px-6">
        <div className="flex flex-wrap items-end gap-x-6 gap-y-3">
          <div className="grid gap-1">
            <h1 className="text-2xl font-semibold tracking-[-0.04em]">
              Requests
            </h1>
            <p className="text-sm text-muted-foreground tabular-nums">
              {logs.length} in the last 30 minutes · {errorRate.toFixed(1)}%
              server errors
            </p>
          </div>
          <Switch
            isSelected={live}
            onChange={setLive}
            className="ms-auto self-center"
          >
            <span className="flex items-center gap-2">
              {live && (
                <span
                  aria-hidden="true"
                  className="size-2 rounded-full bg-success motion-safe:animate-pulse"
                />
              )}
              Live tail
            </span>
          </Switch>
        </div>

        <LogHistogram logs={matching} end={logs[0]?.time ?? 0} />

        <div className="flex flex-wrap items-center gap-2">
          <SearchField
            aria-label="Search requests"
            placeholder="Path, status, or request ID"
            size="sm"
            value={query}
            onChange={setQuery}
            className="w-full sm:w-80"
          />
          <ToggleButtonGroup
            aria-label="Status"
            size="sm"
            selectionMode="single"
            disallowEmptySelection
            selectedKeys={[filter]}
            onSelectionChange={(keys) => {
              const [key] = keys;
              if (
                key === "all" ||
                key === "success" ||
                key === "client" ||
                key === "server"
              ) {
                setFilter(key);
              }
            }}
          >
            <ToggleButton id="all" variant="segmented">
              All{" "}
              <span className="text-muted-foreground tabular-nums">
                {counts.all}
              </span>
            </ToggleButton>
            {statusClasses.map((item) => (
              <ToggleButton key={item.id} id={item.id} variant="segmented">
                {item.name}{" "}
                <span className="text-muted-foreground tabular-nums">
                  {counts[item.id]}
                </span>
              </ToggleButton>
            ))}
          </ToggleButtonGroup>
        </div>

        <div className="h-[34rem] overflow-hidden rounded-xl bg-card ring-1 ring-border/70">
          <ResizableGroup defaultLayout={[58, 42]} className="h-full">
            <ResizablePanel
              id="logs-list"
              minSize={40}
              className="flex flex-col"
            >
              <div
                aria-hidden="true"
                className="grid shrink-0 grid-cols-[4.5rem_2.5rem_minmax(0,1fr)] sm:grid-cols-[4.5rem_3.25rem_3rem_minmax(0,1fr)_4rem] gap-3 border-b border-border/70 px-4 py-2 text-xs font-medium text-muted-foreground"
              >
                <span>Time</span>
                <span className="max-sm:hidden">Method</span>
                <span>Status</span>
                <span>Path</span>
                <span className="text-end max-sm:hidden">Duration</span>
              </div>
              <div className="min-h-0 flex-1">{list}</div>
            </ResizablePanel>
            <ResizableHandle
              aria-label="Resize the request list and the details"
              className="max-lg:hidden"
            />
            <ResizablePanel
              id="logs-details"
              minSize={28}
              className="max-lg:hidden"
            >
              <ScrollArea className="h-full" aria-label="Request details">
                <div className="p-5">
                  {selected ? (
                    <LogDetails entry={selected} />
                  ) : (
                    <p className="text-sm text-muted-foreground">
                      Select a request to see the details.
                    </p>
                  )}
                </div>
              </ScrollArea>
            </ResizablePanel>
          </ResizableGroup>
        </div>
      </main>

      <Sheet
        position="right"
        size="md"
        isOpen={sheetOpen && !isWide}
        onOpenChange={setSheetOpen}
      >
        <SheetHeader>
          <SheetTitle>Request</SheetTitle>
          <SheetClose />
        </SheetHeader>
        <SheetBody className="pb-5">
          {selected && <LogDetails entry={selected} />}
        </SheetBody>
      </Sheet>
    </div>
  );
}

"use client";

import { barY, defineChart, stack } from "@tanstack/charts";
import { scaleBand } from "@tanstack/charts/scales/band";
import { scaleLinear } from "@tanstack/charts/scales/linear";
import { tooltip } from "@tanstack/charts/tooltip";
import { useMemo } from "react";
import {
  Chart,
  ChartFrame,
  ChartLegend,
  ChartLegendItem,
  ChartTable,
} from "../../vip-ui/chart";
import {
  formatClock,
  type LogEntry,
  statusClass,
  statusClasses,
  windowMinutes,
} from "./data";

export function LogHistogram({ logs, end }: { logs: LogEntry[]; end: number }) {
  const buckets = useMemo(() => {
    const last = Math.floor(end / 60_000) * 60_000;
    return Array.from({ length: windowMinutes }, (_, index) => {
      const start = last - (windowMinutes - 1 - index) * 60_000;
      const inside = logs.filter(
        (entry) => entry.time >= start && entry.time < start + 60_000,
      );
      return {
        start,
        label: formatClock(start).slice(0, 5),
        success: inside.filter(
          (entry) => statusClass(entry.status) === "success",
        ).length,
        client: inside.filter((entry) => statusClass(entry.status) === "client")
          .length,
        server: inside.filter((entry) => statusClass(entry.status) === "server")
          .length,
      };
    });
  }, [logs, end]);

  const definition = useMemo(() => {
    const rows = buckets.flatMap((bucket) =>
      statusClasses.map((item) => ({
        minute: bucket.label,
        group: item.name,
        count: bucket[item.id],
      })),
    );
    const top = Math.max(
      4,
      ...buckets.map(
        (bucket) => bucket.success + bucket.client + bucket.server,
      ),
    );
    const ticks = buckets
      .filter((_, index) => (windowMinutes - 1 - index) % 5 === 0)
      .map((bucket) => bucket.label);
    return defineChart({
      marks: [
        barY(rows, {
          x: "minute",
          y: "count",
          z: "group",
          color: "group",
          layout: stack(),
          inset: 1,
          radius: { end: 2, stack: "outer" },
        }),
      ],
      scales: {
        x: {
          scale: () => scaleBand().padding(0.2),
          axis: { ticks: { values: ticks }, tickLabels: { fontSize: 12 } },
        },
        y: {
          scale: scaleLinear().domain([0, Math.ceil(top / 2) * 2]),
          grid: true,
          axis: { ticks: { count: 2 }, tickLabels: { fontSize: 12 } },
        },
      },
      color: {
        domain: statusClasses.map((item) => item.name),
        range: statusClasses.map((item) => item.color),
      },
      focus: "group-x",
      tooltip: {
        use: tooltip,
        sort: "color-domain",
        content: (points, { primaryPoint }) => ({
          title: `${points[0].datum.minute} UTC`,
          rows: points.map((point) => ({
            label: point.groupLabel,
            value: `${point.datum.count}`,
            color: point.color,
            active: point === primaryPoint,
          })),
        }),
      },
    });
  }, [buckets]);

  return (
    <ChartFrame variant="card">
      <Chart
        definition={definition}
        height={112}
        initialWidth={1100}
        ariaLabel={`Requests per minute for the last ${windowMinutes} minutes, by status`}
      />
      <ChartLegend className="justify-start text-xs">
        {statusClasses.map((item) => (
          <ChartLegendItem key={item.id} color={item.color}>
            {item.name}
          </ChartLegendItem>
        ))}
      </ChartLegend>
      <ChartTable
        caption="Requests per minute by status"
        columns={["Minute (UTC)", ...statusClasses.map((item) => item.name)]}
        rows={buckets.map((bucket) => [
          bucket.label,
          bucket.success,
          bucket.client,
          bucket.server,
        ])}
      />
    </ChartFrame>
  );
}
